{"cards": [{"node_code": "N_8740bba1d8d3b61c", "definition": "阴阳五行学说是中医基础理论的核心哲学框架，研究阴阳对立统一规律及五行生克制化关系，用于阐释人体生理、病理及诊疗原则。", "boundary": "本节点收录阴阳与五行的基本概念、属性分类、相互关系及其在中医理论中的具体应用。包括阴阳平衡、五行生克乘侮等机制分析。不收录具体的脏腑功能描述（属藏象）或具体的药物配伍（属方药），仅关注其作为理论模型的逻辑结构。", "includes": ["阴阳学说：对立、互根、消长、转化规律", "五行学说：木火土金水属性、生克制化关系", "阴阳五行在解释生理病理中的模型应用"], "excludes": ["具体脏腑的形态与功能细节", "具体方剂的组成与配伍"], "sibling_distinctions": [{"other_code": "N_31022797bb6224a0", "rule": "阴阳五行是抽象的理论模型和逻辑工具，藏象学说是基于该模型对具体脏腑系统功能属性的描述。"}, {"other_code": "N_d78922c5cf5a9298", "rule": "阴阳五行侧重宏观规律与关系，气血津液侧重构成人体的具体物质基础及其运动变化。"}], "cross_boundary_rule": "若内容侧重哲学本体论探讨，主挂载本节点；若侧重具体脏腑或物质的阴阳五行属性归类，可次关联藏象或气血津液节点。"}, {"node_code": "N_31022797bb6224a0", "definition": "藏象学说是研究人体脏腑生理功能、病理变化及其相互关系的理论，以五脏为中心，结合六腑、奇恒之腑构建整体功能系统。", "boundary": "本节点收录五脏（心肝脾肺肾）及六腑、奇恒之腑的功能特性、生理联系、病理表现及诊断依据。强调“藏精于内，象现于外”的功能系统观，而非解剖形态。不收录经络循行路线（属经络）或气血津液的具体代谢过程（属气血津液）。", "includes": ["五脏的生理功能、特性及相互关系", "六腑与奇恒之腑的功能特点", "脏腑病机分析及脏腑辨证基础"], "excludes": ["经络系统的循行与腧穴分布", "气血津液的生成、运行与代谢细节"], "sibling_distinctions": [{"other_code": "N_8740bba1d8d3b61c", "rule": "藏象是阴阳五行理论在人体器官功能系统上的具体化应用，阴阳五行是藏象的理论基础。"}, {"other_code": "N_1faecf2c6e5488a0", "rule": "藏象侧重脏腑内部的功能系统，经络侧重连接脏腑肢体的通道网络，二者共同构成中医整体观。"}], "cross_boundary_rule": "若内容涉及脏腑功能与经络联系的交叉，主挂载藏象；若侧重经络本身的循行与主治，主挂载经络。"}, {"node_code": "N_d78922c5cf5a9298", "definition": "气血津液学说是研究气、血、津液的生成、运行、生理功能、病理变化及其相互关系的理论，是构成人体和维持生命活动的基本物质。", "boundary": "本节点收录气（元气、宗气等）、血、津液（津、液）的概念、生成来源、运行途径、生理作用及病理表现。重点阐述三者之间的相互依存、相互转化关系。不收录脏腑如何产生这些物质（属藏象）或经络如何输送这些物质（属经络）。", "includes": ["气的分类、生成、运行及功能", "血的生成、运行、功能及病理", "津液的代谢、分布及与气血的关系"], "excludes": ["脏腑具体的生理功能描述", "经络的循行路线与腧穴定位"], "sibling_distinctions": [{"other_code": "N_31022797bb6224a0", "rule": "气血津液是物质基础，藏象是功能系统；藏象研究脏腑如何化生气血津液，气血津液研究这些物质如何滋养脏腑。"}, {"other_code": "N_1faecf2c6e5488a0", "rule": "气血津液是运行于体内的物质，经络是运行气血津液的通道，二者是“流”与“渠”的关系。"}], "cross_boundary_rule": "若内容侧重物质本身的性质与变化，主挂载本节点；若侧重脏腑对物质的代谢调控，可次关联藏象。"}]}
